import hashlib
def canon(s):
    out = ['"']
    for ch in s:
        o = ord(ch)
        if ch in '"\\': out.append('\\' + ch)
        elif o < 0x20: out.append('\\u%04x' % o)
        else: out.append(ch)
    out.append('"')
    return ''.join(out)
prev1 = '0'*64
p1 = '[1,%s,%s,%s,%s,%s,%s]' % (canon('alice'),canon('login'),canon('console'),canon('success'),canon('2026-10-05T00:30:00.250Z'),canon(prev1))
h1 = hashlib.sha256(p1.encode()).hexdigest()
print(h1, h1 == '040968616d4c862c25c6e140ec646baab8a9949d257da9dfe0d9cdff9096a663')
p2 = '[2,%s,%s,%s,%s,%s,%s]' % (canon('a"b\nc'),canon('op'),canon('res'),canon('ok'),canon('2026-10-05T00:00:00Z'),canon(h1))
h2 = hashlib.sha256(p2.encode()).hexdigest()
